    {
      "chord_quality": "maj7",
      "function_role": "i-chord-harmonic-family",
      "narrative": "Greene establishes maj7 as the I chord in modern major-key harmony, listing the full extension family in Chapter 4 (p.15): C, C\u25b3, C6, C/9, C6/9, C2, C4/5, with parenthetical extensions C\u25b3/6 and Csus. Use any of these on the I chord according to context, treating the bare triad as the minimal option.",
      "source_principle_ids": [],
      "source_work_id": "modern-chord-progressions",
      "references": [
        {
