    },
    {
      "chord_quality": "min7",
      "function_role": "substitution-for-maj7-iv",
      "narrative": "Greene states in Ch.5 (p.17): 'ii can substitute for IV because they are virtually the same chord \u2014 like F#m7 = A6 (the homonym concept).' The diatonic ii min7 is interchangeable with the IV chord when shared tones allow.",
      "source_principle_ids": [],
      "source_work_id": "modern-chord-progressions",
